python3 - <<'PY'
import openpyxl, re
from openpyxl.utils import get_column_letter

wb=openpyxl.load_workbook('/root/data/workbook.xlsx', data_only=False)
ws=wb['Data']

# Find non-empty cells in first 60 rows, first 100 cols
nonempty=[]
for r in range(1,61):
    for c in range(1,101):
        v=ws.cell(r,c).value
        if v not in (None,''):
            nonempty.append((r,c,v))

print('Non-empty cells in Data A1:CV60 (first 100 cols):', len(nonempty))
for r,c,v in nonempty[:200]:
    print(f"{get_column_letter(c)}{r}: {v}")
if len(nonempty)>200:
    print('... (truncated)')

# Specifically look for row 20 headers across first 200 cols
headers=[]
for c in range(1,201):
    v=ws.cell(20,c).value
    if v not in (None,''):
        headers.append((c,v))
print('\nRow 20 headers non-empty count:', len(headers))
for c,v in headers[:50]:
    print(f"{get_column_letter(c)}20: {v}")

# Find year header positions anywhere in first 200 cols, rows 1-40
years={2018,2019,2020,2021,2022}
year_hits=[]
for r in range(1,41):
    for c in range(1,201):
        v=ws.cell(r,c).value
        if v in years or (isinstance(v,str) and v.isdigit() and int(v) in years):
            year_hits.append((r,c,v))
print('\nYear hits (2018-2022) in Data sheet rows1-40 cols1-200:', len(year_hits))
for r,c,v in year_hits:
    print(f"{get_column_letter(c)}{r}: {v}")

# Find series code cell locations for pattern *_REN_GEN etc rows 1-100 cols1-50
code_re=re.compile(r'^[A-Z]{3}_(REN_GEN|GRID_USE|BASE_DEMAND)$')
code_hits=[]
for r in range(1,101):
    for c in range(1,51):
        v=ws.cell(r,c).value
        if isinstance(v,str) and code_re.match(v):
            code_hits.append((r,c,v))
print('\nSeries code hits in rows1-100 cols1-50:', len(code_hits))
for r,c,v in code_hits[:100]:
    print(f"{get_column_letter(c)}{r}: {v}")

PY

