python3 - <<'PY'
import openpyxl

wb=openpyxl.load_workbook('/root/data/workbook.xlsx', data_only=False)
found=[]
for ws in wb.worksheets:
    for row in ws.iter_rows():
        for c in row:
            if isinstance(c.value,str) and c.value.startswith('=') and '_xlfn.' in c.value:
                found.append((ws.title,c.coordinate,c.value))

print('Found _xlfn formulas:', len(found))
for item in found[:50]:
    print(item)
